package ru.fkit.bi.analytics.signal;

import java.util.*;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionTemplate;
import ru.fkit.bi.analytics.api.BusinessException;
import ru.fkit.bi.analytics.signal.SignalModels.*;

@Service
class SignalService {
  private final SignalRepository repository;private final TransactionTemplate transactions;
  SignalService(SignalRepository repository,TransactionTemplate transactions){this.repository=repository;this.transactions=transactions;}
  Page<Signal> page(UUID machine,UUID component,String status,String semantic,String kind,Boolean featured,String search,int p,int z){if(!repository.machineExists(machine))throw missing("Machine");validStatus(status);pageBounds(p,z);if(component!=null&&!repository.componentOwned(machine,component))throw new BusinessException(409,"SIGNAL_COMPONENT_OWNER_CONFLICT","Component must belong to the same machine");long n=repository.count(machine,component,status,semantic,kind,featured,search);return new Page<>(repository.page(machine,component,status,semantic,kind,featured,search,p,z),new Metadata(p,z,n,(int)((n+z-1)/z)));}
  Signal create(UUID machine,Create x){if(!repository.machineExists(machine))throw missing("Machine");return transactions.execute(s->{repository.lockMachine(machine);validate(machine,x.componentId(),x.valueType(),x.signalKind(),x.semanticCode(),x.customSemanticCode(),x.unitCode(),x.expectedIntervalMs(),x.staleAfterMs(),x.validMin(),x.validMax());validateMetricSemantic(machine,x.signalKind(),x.semanticCode(),"ACTIVE",null);try{return repository.create(UUID.randomUUID(),machine,x);}catch(DuplicateKeyException e){throw new BusinessException(409,"SIGNAL_CODE_CONFLICT","Signal code already exists in machine");}});}
  Signal get(UUID id){return repository.find(id).orElseThrow(()->missing("TelemetrySignal"));}
  Signal update(UUID id,Update x){return transactions.execute(s->{Signal old=get(id);repository.lockMachine(old.machineId());repository.exclusiveSignalLock(id);old=get(id);validate(old.machineId(),x.componentId(),x.valueType(),x.signalKind(),x.semanticCode(),x.customSemanticCode(),x.unitCode(),x.expectedIntervalMs(),x.staleAfterMs(),x.validMin(),x.validMax());validateMetricSemantic(old.machineId(),x.signalKind(),x.semanticCode(),old.status(),id);if(repository.rawUsed(id)&&(!old.valueType().equals(x.valueType())||!old.signalKind().equals(x.signalKind())||!old.semanticCode().equals(x.semanticCode())||!Objects.equals(old.customSemanticCode(),x.customSemanticCode())||!Objects.equals(old.unitCode(),x.unitCode())))throw new BusinessException(409,"SIGNAL_SEMANTICS_LOCKED","Signal semantic fields cannot change after first raw use");try{repository.update(id,x);}catch(DuplicateKeyException e){throw new BusinessException(409,"SIGNAL_CONFLICT","Signal conflicts with existing configuration");}return get(id);});}
  Signal status(UUID id,StatusUpdate x){return transactions.execute(s->{Signal current=get(id);repository.lockMachine(current.machineId());current=get(id);validateMetricSemantic(current.machineId(),current.signalKind(),current.semanticCode(),x.status(),id);if("DISABLED".equals(x.status())&&"ACTIVE".equals(current.status())&&repository.referencedByActiveStateMachine(id))throw new BusinessException(409,"SIGNAL_USED_BY_ACTIVE_STATE_CONFIG","Signal is referenced by active machine state configuration");repository.status(id,x.status());return get(id);});}
  private void validateMetricSemantic(UUID machine,String kind,String semantic,String targetStatus,UUID except){if("ACTIVE".equals(targetStatus)&&"COUNTER".equals(kind)&&Set.of("PRODUCTION_COUNT","SCRAP_COUNT").contains(semantic)&&repository.activeMetricSemanticExists(machine,semantic,except))throw new BusinessException(409,"METRIC_SIGNAL_SEMANTIC_CONFLICT","A machine can have only one active counter signal for each production metric semantic");}
  private void validate(UUID machine,UUID component,String valueType,String signalKind,String semantic,String custom,String unit,Long interval,Long stale,Double min,Double max){if(component!=null&&!repository.componentOwned(machine,component))throw new BusinessException(409,"SIGNAL_COMPONENT_OWNER_CONFLICT","Компонент должен принадлежать той же машине");if(!Set.of("DOUBLE","LONG","BOOLEAN","STRING").contains(valueType)||!Set.of("GAUGE","COUNTER","STATE").contains(signalKind))throw new BusinessException(422,"SIGNAL_TYPE_INVALID","Тип значения или вид сигнала не поддерживается");boolean combination=(Set.of("GAUGE","COUNTER").contains(signalKind)&&Set.of("DOUBLE","LONG").contains(valueType))||("STATE".equals(signalKind)&&Set.of("BOOLEAN","LONG","STRING").contains(valueType));if(!combination)throw new BusinessException(422,"SIGNAL_TYPE_KIND_MISMATCH","Вид сигнала несовместим с типом значения");if(!repository.catalogSemantic(semantic))throw new BusinessException(422,"SIGNAL_SEMANTIC_INVALID","Выберите активную семантику из справочника");if(("CUSTOM".equals(semantic))!=(custom!=null)||custom!=null&&!custom.matches("^[A-Z][A-Z0-9_]{0,63}$"))throw new BusinessException(422,"SIGNAL_CUSTOM_SEMANTIC_INVALID","Для CUSTOM нужен корректный customSemanticCode");if(!repository.catalogUnit(unit))throw new BusinessException(422,"VALIDATION_FAILED","Проверьте поля сигнала",List.of(new ru.fkit.bi.analytics.api.ErrorResponse.FieldError("unitCode","UNKNOWN_UNIT","Выберите активную единицу из справочника")),Map.of());if(interval!=null&&interval<1||stale!=null&&stale<1||interval!=null&&stale!=null&&stale<interval)throw new BusinessException(422,"SIGNAL_FRESHNESS_INVALID","Интервалы должны быть положительными, staleAfterMs не меньше expectedIntervalMs");if(min!=null&&!Double.isFinite(min)||max!=null&&!Double.isFinite(max)||min!=null&&max!=null&&min>max)throw new BusinessException(422,"SIGNAL_BOUNDS_INVALID","Границы должны быть конечными и упорядоченными");if((min!=null||max!=null)&&!Set.of("DOUBLE","LONG").contains(valueType))throw new BusinessException(422,"SIGNAL_BOUNDS_TYPE_INVALID","Границы допустимы только для числового сигнала");}
  private static void validStatus(String v){if(!Set.of("ACTIVE","DISABLED").contains(v))throw new BusinessException(400,"INVALID_STATUS_FILTER","status must be ACTIVE or DISABLED");}
  private static void pageBounds(int p,int z){if(p<0||z<1||z>200)throw new BusinessException(400,"INVALID_PAGINATION","page must be non-negative and size must be 1..200");}
  private static BusinessException missing(String value){return new BusinessException(404,"NOT_FOUND",value+" not found");}
}
